.cal{width:308px;padding:12px;border:1px solid #d4d4d4;border-radius:12px;font:14px system-ui,sans-serif}
.cal__h{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.cal__h button{width:44px;height:44px;border:0;border-radius:8px;background:none;font-size:20px}
.cal__g{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center}
.cal__g span{font:700 11px ui-monospace,monospace;color:#525252;padding:4px}
.cal__g button{height:40px;border:0;border-radius:8px;background:none;font:inherit;cursor:pointer}
.cal__g button[aria-pressed=true]{background:#0a0a0a;color:#fff;font-weight:700}
/* interaction */
.cal__g .blank{padding:0}.cal__g button:focus-visible{outline:2px solid #1d4ed8;outline-offset:2px}

