document.querySelectorAll('.cal').forEach(cal => {
  const title = cal.querySelector('.cal__h b'), grid = cal.querySelector('.cal__g');
  const [prev, next] = cal.querySelectorAll('.cal__h button');
  let view = new Date(2026, 10, 1), picked = new Date(2026, 10, 9);
  const same = (a, b) => a && b && a.getTime() === b.getTime();
  function draw(focusDay) {
    const label = view.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    title.textContent = label; cal.setAttribute('aria-label', label);
    grid.querySelectorAll('button, .blank').forEach(n => n.remove());
    const days = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate();
    for (let i = 0; i < view.getDay(); i++) grid.insertAdjacentHTML('beforeend', '<span class="blank" aria-hidden="true"></span>');
    for (let d = 1; d <= days; d++) {
      const date = new Date(view.getFullYear(), view.getMonth(), d), b = document.createElement('button');
      b.type = 'button'; b.textContent = d; b.setAttribute('aria-label', date.toLocaleDateString('en-US', { dateStyle: 'full' }));
      b.setAttribute('aria-pressed', String(same(date, picked)));
      b.tabIndex = (picked && picked.getMonth() === view.getMonth() ? same(date, picked) : d === 1) ? 0 : -1;
      b.addEventListener('click', () => { picked = date; draw(d); });
      grid.appendChild(b);
    }
    if (focusDay) grid.querySelectorAll('button')[focusDay - 1].focus();
  }
  prev.addEventListener('click', () => { view = new Date(view.getFullYear(), view.getMonth() - 1, 1); draw(); });
  next.addEventListener('click', () => { view = new Date(view.getFullYear(), view.getMonth() + 1, 1); draw(); });
  grid.addEventListener('keydown', e => {
    const days = [...grid.querySelectorAll('button')], i = days.indexOf(document.activeElement);
    const step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key];
    if (i < 0 || (step === undefined && e.key !== 'Home' && e.key !== 'End')) return;
    e.preventDefault();
    const n = e.key === 'Home' ? 0 : e.key === 'End' ? days.length - 1 : i + step;
    if (days[n]) { days.forEach(b => b.tabIndex = -1); days[n].tabIndex = 0; days[n].focus(); }
  });
  draw();
});
